package com.jmadsen.dashhop;
import android.content.*;import android.graphics.Color;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;
/** A native utility; manual editing is explicitly designated for parked use, not a motion lockout. */
final class NotepadPanel extends LinearLayout {
 final NoteStore store;final ExecutorService worker=Executors.newSingleThreadExecutor();final Handler h=new Handler(Looper.getMainLooper());final LinearLayout content;final TextView status;final CheckBox parked;EditText editor;String editing;boolean closed,saving;volatile int revision;final Object saves=new Object();
 NotepadPanel(Context c){super(c);store=new NoteStore(c);setOrientation(VERTICAL);status=text("Local notes · input from your Android keyboard",14);addView(status);parked=new CheckBox(c);parked.setText("I am parked — enable typing / editing");parked.setTextColor(Color.WHITE);parked.setOnCheckedChangeListener((v,on)->{if(editor!=null)setEditable(on);});addView(parked);LinearLayout actions=new LinearLayout(c);actions.addView(button("Saved Notes",this::list),new LayoutParams(0,-2,1));actions.addView(button("New Note",()->edit(null,"")),new LayoutParams(0,-2,1));addView(actions);content=new LinearLayout(c);content.setOrientation(VERTICAL);addView(content,new LayoutParams(-1,0,1));list();}
 TextView text(String s,int size){TextView t=new TextView(getContext());t.setText(s);t.setTextColor(Color.WHITE);t.setTextSize(size);t.setPadding(6,6,6,6);return t;}
 TextView button(String s,Runnable action){TextView t=text(s,16);t.setGravity(Gravity.CENTER);t.setMinHeight(UtilityPopupManager.px(48));t.setOnClickListener(v->action.run());return t;}
 void hideKeyboard(){if(editor!=null){android.view.inputmethod.InputMethodManager ime=getContext().getSystemService(android.view.inputmethod.InputMethodManager.class);if(ime!=null)ime.hideSoftInputFromWindow(editor.getWindowToken(),0);editor.clearFocus();}}
 void setEditable(boolean on){if(editor!=null){if(!on)hideKeyboard();editor.setFocusable(on);editor.setFocusableInTouchMode(on);}}
 void cancel(){cancel(false);}
 void cancel(boolean explicit){hideKeyboard();synchronized(saves){revision++;}if(explicit)status.setText("Unsaved draft discarded");editing=null;if(editor!=null)editor.setText("");}
 void list(){if(closed)return;cancel();editor=null;content.removeAllViews();content.addView(text("Loading saved notes…",16));int token=revision;worker.execute(()->{try{List<NoteStore.Note> notes=store.list();h.post(()->{if(closed||token!=revision)return;content.removeAllViews();ScrollView sc=new ScrollView(getContext());LinearLayout rows=new LinearLayout(getContext());rows.setOrientation(VERTICAL);sc.addView(rows);content.addView(sc,new LayoutParams(-1,-1));if(notes.isEmpty())rows.addView(text("No saved notes. Tap New Note.",17));for(NoteStore.Note n:notes){String date=java.text.DateFormat.getDateTimeInstance().format(new Date(n.modified));TextView row=button(date+"\n"+(n.text.length()>100?n.text.substring(0,100)+"…":n.text),()->view(n));rows.addView(row);}});}catch(RuntimeException e){error("Unable to read notes",e);}});}
 void view(NoteStore.Note note){cancel();content.removeAllViews();editor=null;ScrollView scroll=new ScrollView(getContext());LinearLayout info=new LinearLayout(getContext());info.setOrientation(VERTICAL);TextView text=text(note.text,19);text.setTextIsSelectable(true);info.addView(text);info.addView(text("Created: "+new Date(note.created)+"\nModified: "+new Date(note.modified),13));info.addView(button("Edit",()->{if(parked.isChecked())edit(note.id,note.text);else status.setText("Confirm parked above to edit manually. No motion lockout is claimed.");}));info.addView(button("Delete",()->{if(!parked.isChecked()){status.setText("Confirm parked above to delete");return;}content.removeAllViews();content.addView(text("Delete this saved note?",20));content.addView(button("Confirm delete",()->worker.execute(()->{try{store.delete(note.id);Diagnostics.info("note_deleted_no_content_logged");h.post(this::list);}catch(RuntimeException e){error("Unable to delete note",e);}})));content.addView(button("Keep note",()->view(note)));}));scroll.addView(info);content.addView(scroll,new LayoutParams(-1,-1));}
 void edit(String id,String initial){cancel();editing=id;content.removeAllViews();editor=new EditText(getContext());editor.setTextColor(Color.WHITE);editor.setHintTextColor(0xffb8cbd0);editor.setHint("Tap here while parked. Type or use your keyboard’s microphone if available; then tap Save.");editor.setText(initial);editor.setGravity(Gravity.TOP);editor.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);setEditable(parked.isChecked());content.addView(editor,new LayoutParams(-1,0,1));LinearLayout actions=new LinearLayout(getContext());actions.addView(button("Save",()->saveNote(editor.getText().toString())),new LayoutParams(0,-2,1));actions.addView(button("Cancel",()->{cancel(true);list();}),new LayoutParams(0,-2,1));content.addView(actions);status.setText("Use your Android keyboard while parked. Keyboard dictation is optional; tap Save to keep the text.");}
 void saveNote(String value){if(closed||saving)return;if(value==null||value.trim().isEmpty()){status.setText("Empty note not saved");return;}hideKeyboard();saving=true;final String id=editing;final int token=revision;worker.execute(()->{try{NoteStore.Note saved;synchronized(saves){saved=store.save(id,value);Diagnostics.info("note_saved_no_content_logged");}h.post(()->{saving=false;if(!closed&&token==revision&&saved!=null){list();status.setText("Note saved locally");}});}catch(RuntimeException e){error("Unable to save note — draft retained",e);}});}
 void error(String message,Exception e){Diagnostics.error("notepad_storage_error",new IllegalStateException(e.getClass().getSimpleName()));h.post(()->{saving=false;if(!closed)status.setText(message);});}
 void close(){if(closed)return;Diagnostics.info("notepad_panel_closing");hideKeyboard();synchronized(saves){closed=true;revision++;}h.removeCallbacksAndMessages(null);worker.execute(store::close);worker.shutdown();}
 protected void onDetachedFromWindow(){close();super.onDetachedFromWindow();}
}
